(19031,'Thank you for bringing back Yi-Mo.$B$BIt\'s clear to me now that we can no longer ignore our duties in the province.','Thank you for bringing back Yi-Mo.$B$BIt\'s clear to me now that we can no longer ignore our duties in the province.',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19045,'We will make this province safe again. Zhu\'s legacy will not end with this.','We will make this province safe again. Zhu\'s legacy will not end with this.',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19067,'Chezin lay dead with grievous wounds both physical and magical.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19080,'The master comes.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19127,'The mogu are usually thugs and brigands. They never struck me as having the patience for arcane magics.','',0,1,1,0,0,0,0,0,'The ruins of Korja were where something important happened sometime, I guess. I may have snoozed through that history lesson.','',0,1,1,0,0,0,0,0,'Did you hear? Dezco named one of the twins "$p".','',0,1,0,0,0,0,0,0,'0',NULL,0,0,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19128,'The first rule of roll club: you don\'t talk about roll club.$B$BThe second rule of roll club: if it\'s your first time, you roll.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19133,'Our envoy was making for the Crane Temple when the mogu ambushed us.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19134,'I\'m confused as to how these raiders are constantly able to assail us no matter how many of them we kill.','',0,1,0,0,0,0,0,0,'These raiders stole the cloths off our dead, the trinkets out of our homes, and the ingots out of our forge. What sort of behavior is that?','',0,1,0,0,0,0,0,0,'The Crane Temple usually comes to our defense and keeps the raiders at bay. But lately they have been quiet.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19135,'Greetings $p. The waters foretold of your arrival. Unfortunately they didn\'t foretell of the raiders hitting us so hard.$b$bI am Waterspeaker Tired Shushen. Welcome to Fallsong.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19259,'I never imagined we\'d run into this much trouble out here.$B$BMaybe we shouldn\'t have left the temple...','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19287,'It seems that after only a few days of study, Anduin already understands the Way of the Crane.$B$BPerhaps he always has?','',0,1,0,0,0,0,0,0,'A $c of your caliber is exactly what we need to turn the battle in our favor.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19323,'I am just glad my wife, spirits guide her, is not around to see our business overrun by these ruffians and hoodlums!','',0,1,1,0,0,0,0,0,'It is an absolute travesty of our time I tell you. That a rancher and his son can\'t just run a yak wash in peace without fear of yaungol raiding...','',0,1,1,0,0,0,0,0,'If this keeps up, I don\'t know how we are ever going to continue our supply of yaks to the grummle.','',0,1,0,0,0,0,0,0,'Have you met the Lucky Eightcoins? He is our biggest customer and the shrewdest of grummle negotiators.','',0,1,1,0,0,0,0,0,'Our business has stood for twelve generations and supplied many hundreds of fresh, clean, and smelly yaks to the grummles.$b$bWe\'ve faced floods, famine, and mogu. I\'ll be a hozen\'s uncle if I let these yaungol run us off.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19324,'You here to steal my yaks?!$b$bIf so, be ready for me to slap that look off your face.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19325,'You saved my son and my ranch. I am forever in your debt, stranger. If you ever find yourself in need of a clean yak, you know where to go.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0);
INSERT INTO `npc_text` (`ID`,`text0_0`,`text0_1`,`lang0`,`prob0`,`em0_0`,`em0_1`,`em0_2`,`em0_3`,`em0_4`,`em0_5`,`text1_0`,`text1_1`,`lang1`,`prob1`,`em1_0`,`em1_1`,`em1_2`,`em1_3`,`em1_4`,`em1_5`,`text2_0`,`text2_1`,`lang2`,`prob2`,`em2_0`,`em2_1`,`em2_2`,`em2_3`,`em2_4`,`em2_5`,`text3_0`,`text3_1`,`lang3`,`prob3`,`em3_0`,`em3_1`,`em3_2`,`em3_3`,`em3_4`,`em3_5`,`text4_0`,`text4_1`,`lang4`,`prob4`,`em4_0`,`em4_1`,`em4_2`,`em4_3`,`em4_4`,`em4_5`,`text5_0`,`text5_1`,`lang5`,`prob5`,`em5_0`,`em5_1`,`em5_2`,`em5_3`,`em5_4`,`em5_5`,`text6_0`,`text6_1`,`lang6`,`prob6`,`em6_0`,`em6_1`,`em6_2`,`em6_3`,`em6_4`,`em6_5`,`text7_0`,`text7_1`,`lang7`,`prob7`,`em7_0`,`em7_1`,`em7_2`,`em7_3`,`em7_4`,`em7_5`,`WDBVerified`) VALUES
(19328,'I honestly don\'t know how I am going to round up so many yaks on my own. Those yaungol are dangerous.','',0,1,1,0,0,0,0,0,'I hope the yaungol arriving wasn\'t a sign of worse things to come. They are bad enough.','',0,1,1,0,0,0,0,0,'Pa says we\'ve faced worse. But when he says "we" he means people like his great great grandfather.$b$bThe worst thing I\'ve ever had to face was a grummle angry that his yak wasn\'t smelly enough.','',0,1,0,0,0,0,0,0,'Mountain sprites are mean creatures. Their pranks can really hurt people.','',0,1,1,0,0,0,0,0,'Pa keeps telling me I need to be more like my grandpa. But he died before I was born in a yak stampede.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19330,'You have no idea how much your help has saved our family business.$b$bI should be able take it from here as long as the yaungol slow down their assault.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19342,'A luckydo would be wise to buy my wares. Bad fortune to those who simply walk away.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19343,'Oh that\'s a fine piece o\' metal you have der. I am quite fond of a good piece of steel.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19352,'It is a luckydo to have a clean yak. It is a bigger luckydo to feed it my special brew. This is how one makes Kobeyaks!','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19414,'One word: Incense!','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19527,'<The crane does not speak, but his words fill your mind.>$B$BGo... while you can...$B$BAll is... lost.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19552,'','We don\'t see very many new faces here anymore.',0,1,1,0,0,0,0,0,'','There aren\'t many willing to brave the mountain pass anymore, friend. Nowadays, some would say you\'d have to be crazy to try.',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19554,'Alchemy is a bit like magic, don\'t you think? With the change of a single ingredient a simple drought can either heal you, or kill you.','',0,1,1,0,0,0,0,0,'My shop is filled with many wonderous and hard to come by things. It would be wise to look, but not to touch.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19555,'Supplies are limited, but I accept only the best from the traders.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19557,'We must never give in to despair.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19562,'My seeds grow the best veggies in the valley. Guaranteed!','',0,100,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,0),
(19563,'Yoon, eh? Never heard of him...','',0,100,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,0),
(19564,'Ohh, of course! The Sunsong place, just over yonder. Was wondering who might be movin\' in on that.$B$B<Greenfield squints over your shoulder and waves at Yoon.>$B$BWhen you come back to market with the biggest, juiciest vegetables anyone\'s ever seen, you tell \'em where you got the seeds!','',0,100,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,NULL,NULL,0,0,0,0,0,0,0,0,0),
(19571,'Brother Brokendice is taking all of my hard earned gold and goods! I should have known not to trust a grummle. Never trust something half your size...','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19578,'Keep the body strong, and the mind will follow.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19584,'Of course!$B$BWhat seems to be the problem?','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19606,'<Miss Fanny looks at you expectantly. Her eye twinkles with anticipation.>$b$b<Miss Fanny\'s moment for glory has arrived.>','',0,1,377,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19608,'When times are dark, it is best to turn on a light.','',0,1,0,0,0,0,0,0,'Do you know why the pandaren love philosophy? Because for them, things are not just black and white.','',0,1,0,0,0,0,0,0,'What happened to the pandaren whose kitchen was robbed? He got bamboozled!','',0,1,0,0,0,0,0,0,'What\'s the most valuable fish in all of Pandaria? The goldfish!','',0,1,0,0,0,0,0,0,'Do you know how to pick up a female jinyu in a tavern? Just drop your line!','',0,1,0,0,0,0,0,0,'What do you call a jinyu who has trained at Tian Monastery? A monkfish!','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19616,'We are the grummles. We know all of the paths through the mountains.$b$bMost of all we bring supplies to the great wall in the east. The bastion of the Shado-Pan.$b$bThese are dark times though, and grummles face great dangers on our road.','',0,1,1,0,0,0,0,0,'Most grummles keep a few luckydos about.$b$bLook, lint in pocket. Big luckydo. Oh, and smelly incense. Very big luckydo.$b$bNever trust unsmellible luck. Sometimes that is luck for someone else.','',0,1,0,0,0,0,0,0,'Some argue Brother Rabbitsfoot has more good fortune than I, the Lucky Eightcoins.$b$bAt this I laugh.$b$bIt is simple: he is called "brother", I am called "Lucky". Obviously I am of more luck.','',0,1,0,0,0,0,0,0,'Never set a yeti on fire. They just get mad.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19617,'Ah! A luckydo comes to the great Grummle Bazaar eh? I smell good fortune in our meeting.$b$bI am called the Lucky Eightcoins. I am named for my best luckydo, the one that gives most pungent smelling fortune.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19621,'Thank the heavens... I thought the secrets of Firebough Stout would die with me. Help me out of here, friend!','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19624,'Allow me to introduce myself - I am Ya Firebough, illustrious leader of this formerly maginificent hamlet.$B$BClearly, you are an upstanding citizen of the world.$B$BI wonder if I could trouble you to help me out of this rather sticky situation? I\'m certain that the Shado-Pan at the nearby retreat will be more than happy to recompense you for any inconvenience.','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19625,'','This is no place for a bright, young $g man : lady; such as yourself.$B$BPerhaps you would like for me to escort you to safety, hmm?',0,1,274,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19630,'We\'ve already lost the town... why have no reinforcements arrived from the Monastery?','',0,1,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19633,'Grummles have good noses. Can tell the difference between good and bad fortune by the smell. You have the smell of good fortune about you.','',0,1,0,0,0,0,0,0,'The Shado-Pan are not here because the wall needs them. Grummles owe much fortune to the Shado-Pan. If the Shado-Pan cannot defend grummles that means they are in danger, and need grummlepacks now more than ever.','',0,1,0,0,0,0,0,0,'The Jib of Dook was a friend of grummles. He lasted a whole three seasons. Now the Ook of Dook is in charge and most angry. He thinks food from grummles will stop soon, so he ravages.','',0,1,0,0,0,0,0,0,'Ah, $rs are most useful. Should have more $rs for rainy day.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19634,'Many good fortunes to you. I am Brother Rabbitsfoot. I am a merchant, a traveller, and a big luckydo for grummles.$b$bIn times of peace, $p would do well to buy of my wares. But fortune has us meet this day.$b$bWe have much work to do together.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19649,'The winds are good today.','',0,1,1,0,0,0,0,0,'Fortune smiles on grummle mounts.','',0,1,1,0,0,0,0,0,'The mountain will forgive the bird, but not always the rider.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,1,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19653,'Thanks again for all your help, $n. The crocolisks aren\'t attacking nearly as much as they were before.$b$bWe\'re also doing our part here. We haven\'t caught any more fish than we need to eat.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19654,'','Hello, $r.',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19665,'There\'s nothing like a good cup of kafa! When the seeds are roasted just right, ground fresh, and brewed in pure water.$B$BPerfect for the weary traveler or studious monk.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19688,'I\'m such a luckydont! I ruined Uncle Keenbean\'s kafa trade!','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19721,'What do you stare at, stranger?','',0,1,0,0,0,0,0,0,'I will not die like this. Not like this!','',0,1,0,0,0,0,0,0,'Go away and leave me be. Let me suffer in peace.','',0,1,0,0,0,0,0,0,'I should have won. I was stronger. Wiser. I would have won against him!','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19722,'','I hear you are the reason my cousin Syra is sending me wedding invitations.$b$bThanks a lot. Now I have to be the unmarried black yak of the family.',0,1,14,1,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19724,'I know a secret trail through Neverrest. Add three days to any journey, but you see very neat waterfall along way. Most fortunate path.','',0,1,1,0,0,0,0,0,'Good fortune to drink coffee before a hike. Bad fortune to drink after.','',0,1,1,0,0,0,0,0,'Rabbitsfoot and Eightcoins argue over who has more luck. Those silly grummles forget that nothing is more lucky than finding lint in your pocket.','',0,1,0,0,0,0,0,0,'A clean yak is a lucky yak. A dirty yak is a yeti attack.','',0,1,1,0,0,0,0,0,'Luck is like lady grummle: hard to find but worth the search.','',0,1,1,0,0,0,0,0,'When counting past 3, continue to 5. Never stop at 4. Most bad fortune for those who stop on four.','',0,1,1,0,0,0,0,0,'Grummles know all roads through mountains. But some grummles know better roads than others.','',0,1,1,0,0,0,0,0,'Most bad fortune with big hozen ravage. Makes for bad travels.','',0,1,1,0,0,0,0,0,0),
(19731,'If I am going to die, I will die with my friends by my side.$b$bI will die knowing I did everything I could to avenge my people.$b$bI will die staring directly into the shamed face of my enemy.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(19732,'Go on, $n. Pull it out. You will not be held accountable for my death, when it comes.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
