(19995,'Something feels... different up here. I don\'t know what, but I expect we shall find out soon enough.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(20012,'To become a Shado-Pan, one must dedicate $Ghimself:herself; in body, mind, and soul.','',0,1,0,0,0,0,0,0,'The Shado-Pan are few in number, but we make up for it in strength.','',0,1,0,0,0,0,0,0,'From the west, the mantid stir.$B$BFrom the northwest, the mogu practice their dark arts.$B$BFrom the north, the yaungol press us.$B$BThere is too much to do, and too little time.','',0,1,0,0,0,0,0,0,'Every Shado-Pan knows one another by name. We have trained together, fought together, and survived together.$B$BWhen you can say the same, then perhaps you are ready to join our brotherhood.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
