(20052,'We are the protectors - immovable and unflappable.$b$bWhen we are moving, nothing can stop us from moving. When we are standing still, nothing can budge us.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
