(21051,'The battlefield is no place for a girl!','',0,1,0,0,0,0,0,0,'If I hadn\'t gotten a splinter I would be out there defending our village too!','',0,1,0,0,0,0,0,0,'Shomi should not want to fight. That is a man\'s job!','',0,1,0,0,0,0,0,0,'Shomi is such a child!','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(21087,'<Duyi looks at you, beaming with pride.>','',0,1,4,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(21088,'','You are welcome here, $r. Please, make yourself at home. There is plenty of food and ale, and there\'s a bed upstairs if you need to rest.  <Maolin smiles warmly at you.>',0,1,2,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
(21094,'Fishing is good for the soul, but crabbing is good for the belly!','',0,1,2,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
