(22569,'Please, keep your voice low, $r. I was sent here by Baine Bloodhoof to keep an eye on events in the Vale.','',0,1,0,0,0,0,0,0,'I am a simple tauren. Baine and I have been friends for a long time.','',0,1,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,'0',NULL,0,0,0,0,0,0,0,0,0),
